import { cloudinaryUrl, isCloudinaryUrl } from '../../../shared/cloudinary'
import manifest from '../../shared/imageManifest.json'

// Responsive WebP variants generated by `npm run images` (scripts/optimize-images.mjs).
export type ImageName = keyof typeof manifest

export interface ImageSource {
  src: string
  srcSet?: string
  width?: number
  height?: number
}

const isBundled = (name: string): name is ImageName => Object.hasOwn(manifest, name)

/**
 * Resolves an image reference. Bundled photography (a manifest key) gets a
 * responsive srcset; Cloudinary uploads from the admin panel get Cloudinary-resized variants.
 */
export function imageSource(name: string): ImageSource {
  if (isCloudinaryUrl(name)) {
    // Uploaded via the admin panel: Cloudinary resizes and picks the best format per browser.
    return {
      src: cloudinaryUrl(name, 1920),
      srcSet: [640, 1280, 1920].map((w) => `${cloudinaryUrl(name, w)} ${w}w`).join(', '),
    }
  }
  if (!isBundled(name)) return { src: name }
  const { widths, ratio } = manifest[name]
  const largest = widths[widths.length - 1]
  return {
    src: `/img/${name}-${largest}.webp`,
    srcSet: widths.map((w) => `/img/${name}-${w}.webp ${w}w`).join(', '),
    width: largest,
    height: Math.round(largest / ratio),
  }
}
